        internal void Prepare(GeneratedImage image)
        {
            heading.Select(0);RefreshProviders();if(image==null)return;var p=pet.Settings.ImageProviders.FirstOrDefault(v=>v.Id==image.ProviderId);if(p!=null)providers.SelectedItem=p;prompt.Text=image.Prompt;size.Text=String.IsNullOrEmpty(image.Size)?"服务默认":image.Size;quality.Text=String.IsNullOrEmpty(image.Quality)?"服务默认":image.Quality;
            reference=null;referenceId=null;missingReference=false;referencePreview.Children.Clear();notice.Text="已填入原提示词和参数，点击“生成图片”发起新的请求。";
            if(!String.IsNullOrEmpty(image.ReferenceImageId))try{var original=pet.ImageStore.Get(image.ReferenceImageId);reference=pet.ImageStore.Read(image.ReferenceImageId);referenceId=image.ReferenceImageId;referenceMedia=original.MediaType;int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(reference,220,out width,out height,out limited);referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});}catch(Exception error){if(!(error is IOException||error is UnauthorizedAccessException||error is ArgumentException))throw;reference=null;missingReference=true;notice.Text="原参考图缺失，请重新上传或明确移除后再生成。";}
            RefreshReferenceAvailability();
        }
        internal void RefreshProviders(){string selected=(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider())==null?null:(providers.SelectedItem as ImageGenerationProvider??pet.Settings.SelectedImageProvider()).Id;providers.ItemsSource=null;providers.ItemsSource=pet.Settings.ImageProviders;providers.SelectedItem=pet.Settings.ImageProviders.FirstOrDefault(p=>p.Id==selected)??pet.Settings.SelectedImageProvider();RefreshReferenceAvailability();}
        void RefreshReferenceAvailability(){if(upload==null||referenceLabel==null)return;var p=providers.SelectedItem as ImageGenerationProvider;upload.IsEnabled=p!=null&&p.SupportsEdits&&!submitting;referenceLabel.Text=reference!=null?"已选择参考图 · "+(reference.Length/1024)+" KB":p==null?"请先配置并选择生图服务。":!p.SupportsEdits?"此服务尚未启用参考图编辑；可在图片生成配置中启用。":"可选：上传一张 PNG、JPEG 或 WebP 参考图。";}
        void PickReference(){var picker=new Microsoft.Win32.OpenFileDialog{Title="选择参考图",Filter="图片|*.png;*.jpg;*.jpeg;*.webp",Multiselect=false};if(picker.ShowDialog(Window.GetWindow(this))!=true)return;try{var info=new FileInfo(picker.FileName);if(info.Length>50L*1024*1024)throw new InvalidOperationException("参考图不能超过 50 MB。");byte[] bytes=File.ReadAllBytes(info.FullName);int width,height;bool limited;var bitmap=ChatImagePreview.DecodeGeneratedImage(bytes,220,out width,out height,out limited);reference=bytes;referenceId=null;missingReference=false;referenceMedia=info.Extension.ToLowerInvariant()==".webp"?"image/webp":info.Extension.ToLowerInvariant()==".png"?"image/png":"image/jpeg";referencePreview.Children.Clear();referencePreview.Children.Add(new Image{Source=bitmap,MaxHeight=130,HorizontalAlignment=HorizontalAlignment.Left});RefreshReferenceAvailability();}catch(Exception e){notice.Text=e is InvalidOperationException?e.Message:"参考图无法读取，请选择有效图片。";}}
        internal async Task GenerateAsync()
        {
            if(disposed||submitting)return;var provider=providers.SelectedItem as ImageGenerationProvider;if(provider==null){notice.Text="请先配置并选择生图服务。";return;}if(String.IsNullOrWhiteSpace(prompt.Text)){notice.Text="请填写提示词。";return;}if(missingReference){notice.Text="原参考图缺失，请重新上传或明确移除参考图。";return;}if(reference!=null&&!provider.SupportsEdits){notice.Text="当前服务未启用参考图编辑，请移除参考图或切换服务。";return;}
            ImageGenerationTaskHandle handle=null;submitting=true;start.IsEnabled=false;RefreshReferenceAvailability();
            try{
                try{handle=await AcceptSubmission(provider);if(!disposed)notice.Text="任务已提交，可继续提交下一项。";}
                finally{submitting=false;if(!disposed){start.IsEnabled=true;RefreshReferenceAvailability();}}
                // Acceptance owns all request/reference snapshots; this continuation retains only a handle.
                await handle.Completion;if(!disposed&&imageJobId==handle.Id)notice.Text="图片已生成并保存";
            }catch(OperationCanceledException){if(!disposed&&(handle==null||imageJobId==handle.Id))notice.Text="已取消生成。";}catch(Exception e){if(!disposed&&(handle==null||imageJobId==handle.Id))notice.Text=e is ApiException||e is InvalidOperationException||e is TimeoutException||e is IOException?e.Message:"生成失败，请检查生图服务和本地存储。";}
        }
        Task<ImageGenerationTaskHandle> AcceptSubmission(ImageGenerationProvider provider)
        {
            var request=new ImageGenerationRequest{Provider=provider.Copy(),Prompt=prompt.Text,Size=ImageGenerationSettings.Optional(size),Quality=ImageGenerationSettings.Optional(quality),ReferenceImageBytes=reference,ReferenceMediaType=referenceMedia,ReferenceImageId=referenceId,SessionId="image-workspace",Persistent=pet.Settings.SaveChatHistory};
            return pet.ImageTasks.EnqueueAsync(new ImageGenerationTaskSubmission(Guid.NewGuid().ToString("N"),request,new ImageTaskOrigin{Source=ImageGenerationSource.Workspace}){BeforeStart=id=>{if(!disposed){imageJobId=id;generated.Children.Clear();generated.Children.Add(ImageGenerationPendingCard.Create(pet,Window.GetWindow(this),id,Prepare));}return Task.FromResult(0);}},CancellationToken.None);
        }
        void TaskChanged(ImageGenerationTaskSnapshot snapshot){if(disposed||Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(delegate{if(!disposed)RefreshTaskCount();}));}
        void RefreshTaskCount(){((TextBlock)heading.Tabs[2].Content).Text="任务 ("+pet.ImageTasks.List().Count(t=>!t.IsTerminal)+")";}
        void RebindTask(){if(disposed||imageJobId!=null)return;var task=pet.ImageTasks.List().LastOrDefault(t=>t.Source==ImageGenerationSource.Workspace);if(task==null)return;imageJobId=task.Id;generated.Children.Clear();generated.Children.Add(ImageGenerationPendingCard.Create(pet,Window.GetWindow(this),task.Id,Prepare));}
        void StoreChanged(){if(disposed||Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(delegate{if(!disposed)RefreshGallery();}));}
        void FilterChanged(){if(filterUpdating)return;galleryLimit=40;selection.Clear();RefreshGallery();}
        void RefreshGallery()
        {
            if(disposed||search==null)return;int revision=++galleryRevision;gallery.Mode=pet.Settings.ImageGalleryLayout;SetLayoutButton(masonryMode,gallery.Mode=="masonry");SetLayoutButton(gridMode,gallery.Mode=="grid");
            DateTime? from,to;if(!ParseDate(fromDate.Text,false,out from)||!ParseDate(toDate.Text,true,out to)){galleryCount.Text="日期格式应为 YYYY-MM-DD。";return;}
            var request=new ImageGalleryQuery{Keyword=search.Text,Trash=trashOnly.IsChecked==true,FavoritesOnly=favoritesOnly.IsChecked==true,ProviderId=galleryProvider.SelectedIndex>0?(galleryProvider.SelectedItem as ImageGalleryProviderChoice).Id:null,Model=galleryModel.SelectedIndex>0?galleryModel.SelectedItem as string:null,OldestFirst=gallerySort.SelectedIndex==1,Limit=galleryLimit,FromUtc=from,ToUtc=to};
            if(gallerySource.SelectedIndex>0)request.Source=gallerySource.SelectedIndex==1?ImageGenerationSource.Workspace:gallerySource.SelectedIndex==2?ImageGenerationSource.Conversation:gallerySource.SelectedIndex==3?ImageGenerationSource.SettingsTest:ImageGenerationSource.Unknown;
            Task.Run(()=>{var options=pet.ImageStore.ListIncludingTrash();return Tuple.Create(new ImageGalleryQueryService(pet.ImageStore).Query(request),options.Select(i=>i.ProviderId).Where(i=>!String.IsNullOrEmpty(i)).Distinct().OrderBy(i=>i).ToArray(),options.Select(i=>i.Model).Where(i=>!String.IsNullOrEmpty(i)).Distinct().OrderBy(i=>i).ToArray());}).ContinueWith(task=>Dispatcher.BeginInvoke(new Action(delegate
            {
                if(disposed||revision!=galleryRevision)return;if(task.IsFaulted){galleryCount.Text="图库读取失败，请检查存储。";return;}
                filterUpdating=true;UpdateProviderOptions(galleryProvider,task.Result.Item2,pet.Settings.ImageProviders);UpdateOptions(galleryModel,"全部模型",task.Result.Item3);filterUpdating=false;
                foreach(ImageGalleryTile tile in gallery.Children)tile.Dispose();gallery.Children.Clear();galleryStatus.Children.Clear();var result=task.Result.Item1;loadedGallery=result.Items;galleryCount.Text="共 "+result.Total+" 张 · 已加载 "+result.Items.Count+" 张 · 已选 "+selection.Count+" 张";
                multiSelect.Content=selecting?"完成多选":"多选";galleryActions.Visibility=selecting?Visibility.Visible:Visibility.Collapsed;clearTrash.Visibility=trashOnly.IsChecked==true?Visibility.Visible:Visibility.Collapsed;trashAction.Visibility=trashOnly.IsChecked==true?Visibility.Collapsed:Visibility.Visible;restoreAction.Visibility=trashOnly.IsChecked==true?Visibility.Visible:Visibility.Collapsed;purgeAction.Visibility=trashOnly.IsChecked==true?Visibility.Visible:Visibility.Collapsed;
                if(result.Total==0)galleryStatus.Children.Add(Ui.Text("图库中还没有匹配图片。",12,Ui.Muted));foreach(var item in result.Items)gallery.Children.Add(new ImageGalleryTile(pet,item,gallery.Mode,Prepare,ToggleSelected,ToggleFavorite,selection.Contains(item.Id),selecting));
                loadMore.Visibility=result.Total>result.Items.Count?Visibility.Visible:Visibility.Collapsed;if(!String.IsNullOrEmpty(pet.ImageStore.Warning))galleryStatus.Children.Add(Ui.Text(pet.ImageStore.Warning,12,Ui.Muted));
            })),TaskScheduler.Default);
        }
        static void UpdateOptions(ComboBox box,string all,string[] choices){string selected=box.SelectedItem as string;box.Items.Clear();box.Items.Add(all);foreach(string choice in choices)box.Items.Add(choice);box.SelectedItem=box.Items.Contains(selected)?selected:all;}
        static void UpdateProviderOptions(ComboBox box,string[] ids,IEnumerable<ImageGenerationProvider> configured){string selected=(box.SelectedItem as ImageGalleryProviderChoice)==null?null:((ImageGalleryProviderChoice)box.SelectedItem).Id;box.Items.Clear();box.Items.Add(new ImageGalleryProviderChoice{Id="",Label="全部服务"});foreach(string id in ids){var provider=configured.FirstOrDefault(p=>p.Id==id);box.Items.Add(new ImageGalleryProviderChoice{Id=id,Label=provider==null?"已移除的服务 · "+id.Substring(0,Math.Min(6,id.Length)):provider.Name});}box.SelectedItem=box.Items.OfType<ImageGalleryProviderChoice>().FirstOrDefault(i=>i.Id==selected)??box.Items[0];}
        static bool ParseDate(string text,bool end,out DateTime? value){return ImageGalleryDateFilter.TryParseDate(text,end,out value);}
        void ToggleSelected(string id){selection.Toggle(id);RefreshGallery();}
        void ToggleFavorite(string id){try{var item=pet.ImageStore.Get(id);pet.ImageStore.SetFavorite(new[]{id},!item.IsFavorite);}catch(Exception error){MessageBox.Show(error.Message,"收藏未保存");}}
        void SetSelectedFavorite(bool value){if(selection.Count==0)return;try{pet.ImageStore.SetFavorite(selection.Ids,value);galleryActionNotice.Text=value?"已收藏所选图片。":"已取消所选图片的收藏。";}catch(Exception error){MessageBox.Show(error.Message,"收藏未保存");}}
        static string ManagementSummary(ImagePurgeResult result){return "已删除 "+result.DeletedIds.Count+" 张；保留 "+result.Blocked.Count+" 张。"+String.Join("；",result.Blocked.Select(i=>i.Key+"："+i.Value))+ (result.CleanupPendingIds.Count>0?"；"+result.CleanupPendingIds.Count+" 张文件待下次清理。":"");}
        void ModifySelected(bool restore){try{if(selection.Count==0)return;if(restore)pet.ImageStore.Restore(selection.Ids);else if(PermissionChangeDialog.Confirm(Window.GetWindow(this),"移入回收站？","将所选 "+selection.Count+" 张图片移入回收站；原聊天仍可查看。"))pet.ImageStore.MoveToTrash(selection.Ids);selection.Clear();RefreshGallery();}catch(Exception error){MessageBox.Show(error.Message,"图库操作失败");}}
        async Task ExportSelectedAsync(){if(selection.Count==0||exportCancellation!=null)return;using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="选择原图导出目录"}){if(picker.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;var source=new CancellationTokenSource();exportCancellation=source;cancelExport.Visibility=Visibility.Visible;var ids=selection.Ids.ToArray();try{int completed=0;var progress=new Progress<ImageExportItem>(item=>{completed++;if(!disposed)galleryCount.Text="正在导出 "+completed+" / "+ids.Length+" 张";});var result=await new ImageGalleryExport(pet.ImageStore,pet.ImageUsage).ExportAsync(ids,picker.SelectedPath,progress,source.Token);galleryCount.Text=(result.Canceled?"已取消；":"")+"已导出 "+result.Completed+" 张，失败 "+result.Failed+" 张。";galleryActionNotice.Text=String.Join("\n",result.Items.Select(i=>i.Id+"："+(i.Path??i.Error??(i.Canceled?"已取消":"未导出"))));}catch(Exception error){MessageBox.Show(error.Message,"导出失败");}finally{exportCancellation=null;cancelExport.Visibility=Visibility.Collapsed;source.Dispose();}}}
        async Task PurgeSelectedAsync(){if(selection.Count==0)return;var ids=selection.Ids.ToArray();try{var preview=await pet.ImageManagement.InspectReferencesAsync(ids,CancellationToken.None);var items=pet.ImageStore.ListIncludingTrash().Where(i=>ids.Contains(i.Id)&&i.TrashedUtc.HasValue).ToList();if(!PermissionChangeDialog.Confirm(Window.GetWindow(this),"永久删除图片？","所选 "+items.Count+" 张，约 "+(items.Sum(i=>i.Bytes)/1024)+" KB。\n仍被引用："+preview.Blocked.Count+" 张；这些图片会保留。"))return;var result=await pet.ImageManagement.PurgeAsync(ids,CancellationToken.None);selection.Clear();galleryActionNotice.Text=ManagementSummary(result);RefreshGallery();}catch(Exception error){galleryActionNotice.Text="无法检查图片引用："+error.Message;}}
        async Task ClearTrashAsync(){try{var items=pet.ImageStore.ListIncludingTrash().Where(i=>i.TrashedUtc.HasValue).ToList();if(items.Count==0){galleryActionNotice.Text="回收站为空。";return;}var ids=items.Select(i=>i.Id).ToArray();var preview=await pet.ImageManagement.InspectReferencesAsync(ids,CancellationToken.None);if(!PermissionChangeDialog.Confirm(Window.GetWindow(this),"清空回收站？","回收站共 "+items.Count+" 张，约 "+(items.Sum(i=>i.Bytes)/1024)+" KB。\n仍被引用："+preview.Blocked.Count+" 张；这些图片会保留。"))return;var result=await pet.ImageManagement.PurgeAsync(ids,CancellationToken.None);selection.Clear();galleryActionNotice.Text=ManagementSummary(result);RefreshGallery();}catch(Exception error){galleryActionNotice.Text="无法检查图片引用："+error.Message;}}
        async Task CleanupOrphansAsync(){try{var preview=await pet.ImageManagement.InspectOrphanReferencesAsync(CancellationToken.None);if(preview.Count==0){galleryActionNotice.Text="没有未使用的私有参考图。";return;}var ids=preview.Candidates.Select(i=>i.Id).ToArray();if(!PermissionChangeDialog.Confirm(Window.GetWindow(this),"清理未使用参考图？","候选 "+preview.Count+" 张，约 "+(preview.TotalBytes/1024)+" KB。确认后会再次检查引用。"))return;var result=await pet.ImageManagement.CleanupOrphanReferencesAsync(ids,CancellationToken.None);galleryActionNotice.Text=ManagementSummary(result);}catch(Exception error){galleryActionNotice.Text="无法检查参考图："+error.Message;}}
        void SetGalleryMode(string mode){pet.Settings.ImageGalleryLayout=mode;pet.SaveSettings();RefreshGallery();}
        static void SetLayoutButton(Button button,bool selected){button.Background=selected?Ui.Pale:System.Windows.Media.Brushes.Transparent;button.Foreground=selected?Ui.Blue:Ui.Muted;button.FontWeight=selected?FontWeights.SemiBold:FontWeights.Normal;}
        internal void ShowTasks(string id){heading.Select(2);taskCenter.SelectTask(id);}
        public void Dispose(){taskCenter.Dispose();if(disposed)return;disposed=true;galleryRevision++;if(exportCancellation!=null)exportCancellation.Cancel();pet.ImageStore.Changed-=StoreChanged;pet.ImageTasks.Changed-=TaskChanged;reference=null;referenceId=null;referencePreview.Children.Clear();generated.Children.Clear();foreach(ImageGalleryTile tile in gallery.Children)tile.Dispose();}
    }
}
